const records = $input.all().map(i => i.json);

// split data
const opportunities = records.filter(r => r.StageName);
const activities = records.filter(r => r.Subject);

// helper classifier
function classifyActivity(subject = "") {
  const s = subject.toLowerCase();

  if (s.includes("call") || s.includes("negotiation") || s.includes("discovery")|| s.includes("check-in") ) return "call";

  if (s.includes("email") || s.includes("outreach")) return "email";

  if (s.includes("follow") || s.includes("follow-up") )return "followup";

  if (s.includes("demo") || s.includes("meeting") || s.includes("review")) return "meeting";
  return "other";
}

const result = opportunities.map(opp => {
  const oppActivities = activities.filter(a => a.WhatId === opp.Id);

  let calls = 0;
  let emails = 0;
  let followups = 0;
  let meetings = 0;

  oppActivities.forEach(act => {
    const type = classifyActivity(act.Subject);
    if (type === "call") calls++;
    if (type === "email") emails++;
    if (type === "followup") followups++;
    if (type === "meeting") meetings++;
  });

  const touches = oppActivities.length;

  const lastDate = oppActivities
    .map(a => a.ActivityDate)
    .filter(Boolean)
    .sort()
    .pop();

  let gap = "No activity";
  if (lastDate) {
    const diff = (new Date() - new Date(lastDate)) / (1000 * 60 * 60 * 24);
    gap = Math.floor(diff);
  }

  return { 
    opportunity: opp.Name,
    rep: opp.OwnerId,
    stage: opp.StageName,
    amount: opp.Amount,
    touches,
    calls,
    emails,
    followups,
    meetings,
    lastActivityDate: lastDate || null,
    lastActivityGapDays: gap
  };
});

return result.map(r => ({ json: r }));

const deals = $input.all().map(i => i.json);
const reps = {};

for (const d of deals) {
  const rep = d.rep || "Unknown Rep";

  if (!reps[rep]) {
    reps[rep] = {
      rep,
      total_deals: 0,
      total_revenue: 0,
      won_deals: 0,
      lost_deals: 0,
      calls: 0,
      emails: 0,
      meetings: 0,
      followups: 0,
      stale_deals: 0
    };
  }

  const r = reps[rep];

  r.total_deals++;
  r.total_revenue += d.amount;
  r.calls += d.calls;
  r.emails += d.emails;
  r.meetings += d.meetings;
  r.followups += d.followups;

  if (d.stage === "Closed Won") r.won_deals++;
  if (d.stage === "Closed Lost") r.lost_deals++;
  if (d.lastActivityGapDays > 7) r.stale_deals++;
}

return Object.values(reps).map(r => ({ json: r }));

// Collect rep rows
const reps = $input.all().map(i => i.json);

// Build arrays
const labels = [$('Get user').first().json.recentItems[0].Name];
const calls = reps.map(r => r.calls);
const emails = reps.map(r => r.emails);
const meetings = reps.map(r => r.meetings);
const wonDeals = reps.map(r => r.won_deals);
const lostDeals = reps.map(r => r.lost_deals);
const staleDeals = reps.map(r => r.stale_deals);

// Build chart config
const chartConfig = {
  type: "bar",
  data: {
    labels,
    datasets: [
      { label: "Calls", data: calls, backgroundColor: "rgba(54,162,235,0.7)" },
      { label: "Emails", data: emails, backgroundColor: "rgba(255,99,132,0.7)" },
      { label: "Meetings", data: meetings, backgroundColor: "rgba(255,206,86,0.7)" },
      { label: "Won Deals", data: wonDeals, backgroundColor: "rgba(75,192,192,0.7)" },
      { label: "Lost Deals", data: lostDeals, backgroundColor: "rgba(255,159,64,0.7)" },
      { label: "Stale Deals", data: staleDeals, backgroundColor: "rgba(153,102,255,0.7)" }
    ]
  },
  options: {
    plugins: {
      title: {
        display: true,
        text: "Weekly Rep Activity vs Outcomes"
      },
      legend: { position: "bottom" }
    },
    scales: { y: { beginAtZero: true } }
  }
};

// Create QuickChart URL
const chartUrl =
  "https://quickchart.io/chart?c=" +
  encodeURIComponent(JSON.stringify(chartConfig));

// Return everything for Gmail node
return [{
  json: {
    labels:[$('Get user').first().json.recentItems[0].Name],
    calls,
    emails,
    meetings,
    wonDeals,
    lostDeals,
    staleDeals,
    chartUrl
  }
}];

