const oppIds = $input.all().map(item => item.json.Id);
const quoted = oppIds.map(id => `'${id}'`);
const oppIdString = quoted.join(",");

return [
  {
    json: {
      opportunityIdsString: oppIdString
    }
  }
];

// Get AI node data
const ai = $items("Generate AI Coaching Insights")[0].json.output;

// Get chart node data
const chart = $items("Generate Performance Chart URL")[0].json;

// Return merged + flattened object
return [{
  json: {
    performance_summary: ai.performance_summary,
    coaching_advice: ai.coaching_advice,
    next_week_actions: ai.next_week_actions,
    risks: ai.risks,
    strengths: ai.strengths,
    chartUrl: chart.chartUrl
  }
}];
